var app = new Hono3();
app.use("*", cors({
  origin: ["https://*.telegram.org", "https://web.telegram.org", "https://telegram.org"],
  allowHeaders: ["Content-Type", "Authorization"],
  allowMethods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"],
  credentials: true
}));
app.route("/api", api);
app.route("/api/internal", internalApi);
app.post("/telegram/webhook", async (c6) => {
  const secretToken = c6.req.header("X-Telegram-Bot-Api-Secret-Token");
  if (secretToken !== c6.env.TELEGRAM_WEBHOOK_SECRET) {
    return c6.json({ ok: false, error: "Invalid webhook secret" }, 401);
  }
  const update = await c6.req.json();
  const bot = new TelegramBot(c6.env);
  const result = await bot.handleWebhook(update);
  return c6.json(result);
});
app.get("/telegram/setup", async (c6) => {
  const bot = new TelegramBot(c6.env);
  const webhookResult = await bot.setWebhook(c6.env.APP_ORIGIN);
  const commandsResult = await bot.setMyCommands();
  const menuResult = await bot.setMenuButton();
  return c6.json({ webhook: webhookResult, commands: commandsResult, menu: menuResult });
});
app.get("/upload*", async (c6) => {
  return c6.redirect(`${c6.env.APP_ORIGIN}/miniapp${c6.req.path.replace("/upload", "")}${c6.req.query() ? "?" + c6.req.query() : ""}`);
});
app.get("*", (c6) => {
  return c6.notFound();
});
var index_default = app;
export {
  index_default as default
};
